// update_subgame @ 0x438b90 (thiscall, ret)

#include <stddef.h>

#include "bod_list.h"
#include "bod_ai_dispatch.h"
#include "fringe_object.h"
#include "sub_solution.h"
#include "new_game_menu.h"
#include "player.h"
