int OSDPrintUV(
    int texture_id,
    float x,
    float y,
    float width,
    float height,
    int flags,
    tColour* color,
    float u0,
    float v0,
    float u1,
    float v1,
    int blend_mode,
    float rotation);
int report_errorf(char* format, ...);

void cRSubGame::AI()
{
    int cell_index;
    int attachment_count;
    tColour replay_color;
    tColour replay_color_alt;
    tColour skirt_color;

    CalcRate();

    switch (subgame_state) {
    case 3:
        subgame_state = 4;
        subgame_pause_gate = (unsigned char)1;
        pause_fade = pause_fade_step;
        sub_pause.Init();
        // Native fallthrough: initialization immediately receives one update.
    case 4:
        sub_pause.AI();
        return;

    case 7:
        if (selected_level_record_persistent == 1) {
            selected_level_record_active = (unsigned char)1;
            StartLevel(0);
            subgame_state = 2;
            g_game->render_skip_count = 1;
            return;
